/**
 * @canvas      Welcome — a single "Hello" artboard · dark studio
 * @ds          maude
 * @platform    desktop
 * @artboards   hello
 * @brief       One artboard called "Hello" that shows a heading saying "Hello".
 * @stack       React 19 · TSX · Bun.build
 */

import "../system/maude/colors_and_type.css";
import { DesignCanvas, DCSection, DCArtboard } from "@maude/canvas-lib";

/* Scoped to the maude DS token ladder via `.maude[data-theme]`. Mirrors GitPanel Board(). */
function Board({ children }: { children: React.ReactNode }) {
  return <div className="maude" data-theme="dark" style={{ position: "absolute", inset: 0 }}>{children}</div>;
}

export default function Welcome() {
  return (
    <DesignCanvas>
      <DCSection id="welcome" title="Welcome">
        <DCArtboard id="hello" label="Hello" width={960} height={600}>
          <Board>
            <main style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", background: "var(--bg-0)" }}>
              <h1 data-cd-id="hello-heading" style={{ margin: 0, fontFamily: "var(--font-display)", fontSize: 64, fontWeight: 600, letterSpacing: "-0.02em", color: "var(--fg-0)" }}>
                Hello
              </h1>
            </main>
          </Board>
        </DCArtboard>
      </DCSection>
    </DesignCanvas>
  );
}

{
  "title": "Welcome",
  "subtitle": "A single Hello artboard",
  "brief": "One artboard called \"Hello\" that shows a heading saying \"Hello\".",
  "platform": "desktop",
  "designSystem": "maude",
  "kind": "canvas",
  "sections": [
    {
      "id": "welcome",
      "title": "Welcome"
    }
  ],
  "artboards": [
    {
      "id": "hello",
      "label": "Hello",
      "note": "Centered \"Hello\" heading on the dark canvas background"
    }
  ]
}

